 const playQuranAudio=async()=>{if(!quranPreview)return;const audio=quranAudioRef.current;if(!audio)return;if(!audio.paused){quranContinuous.current=false;audio.pause();setQuranAudioPlaying(false);return;}quranAudioFinished.current=false;setQuranAudioLoading(true);try{await audio.play();setQuranAudioPlaying(true)}catch{setQuranAudioPlaying(false)}finally{setQuranAudioLoading(false)}};
